  ?z a brick:Zone .
  ?z rdfs:label ?zone_name .
  FILTER(?zone_name IN ("Core_bottom","Perimeter_bot_ZN_4","Perimeter_top_ZN_1"))
}

SELECT ?z ?label ?cls WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
  ?z rdfs:subClassOf ?cls .
} LIMIT 100

SELECT ?s ?label WHERE {
  ?s a brick:ElectricPowerSensor .
  OPTIONAL { ?s rdfs:label ?label }
}

